def pad_iso_date(s):
    y, m, d = s.split("-")
    return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"

def count_leading_zeros(s):
    count = 0
    for ch in s:
        if ch == '0':
            count += 1
        else:
            break
    return count

def age_difference_in_years(birth1, birth2, today):
    def age(birth):
        by, bm, bd = birth
        ty, tm, td = today
        y = ty - by
        if (tm, td) < (bm, bd):
            y -= 1
        return y
    return age(birth1) - age(birth2)

def split_by_threshold(lst, t):
    below = [x for x in lst if x < t]
    at_or_above = [x for x in lst if x >= t]
    return (below, at_or_above)

def rotate_string_left(s, n):
    if not s:
        return ""
    n = n % len(s)
    return s[n:] + s[:n]

def least_frequent_char(s):
    if not s:
        return ""
    freq = {}
    order = []
    for ch in s:
        if ch not in freq:
            freq[ch] = 0
            order.append(ch)
        freq[ch] += 1
    best = order[0]
    for ch in order[1:]:
        if freq[ch] < freq[best]:
            best = ch
    return best

def season_from_month(month_index):
    month = (month_index - 1) % 12 + 1
    if month in (12, 1, 2):
        return 'Winter'
    if month in (3, 4, 5):
        return 'Spring'
    if month in (6, 7, 8):
        return 'Summer'
    return 'Fall'

def partial_reveal_phone(digits, keep_first, keep_last):
    n = len(digits)
    if keep_first + keep_last >= n:
        return digits
    return digits[:keep_first] + "*" * (n - keep_first - keep_last) + digits[-keep_last:]

def interleave_multiple_lists(lists):
    out = []
    i = 0
    while True:
        added = False
        for lst in lists:
            if i < len(lst):
                out.append(lst[i])
                added = True
        if not added:
            break
        i += 1
    return out

def count_char_type_groups(s):
    if not s:
        return 0
    def kind(ch):
        if ch.isalpha():
            return 'alpha'
        if ch.isdigit():
            return 'digit'
        return 'other'
    groups = 1
    for i in range(1, len(s)):
        if kind(s[i]) != kind(s[i-1]):
            groups += 1
    return groups

def lookup_chain(d, keys):
    cur = d
    for k in keys:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return None
    return cur

def truncate_ellipsis(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    return s[:maxlen - 3] + '...'

def reverse_in_chunks(lst, k):
    out = []
    for i in range(0, len(lst), k):
        out.extend(reversed(lst[i:i+k]))
    return out

def condense_whitespace(s):
    result = []
    prev_space = False
    for c in s:
        if c.isspace():
            if not prev_space:
                result.append(' ')
            prev_space = True
        else:
            result.append(c)
            prev_space = False
    return "".join(result).strip()

def move_char_to_front(s, ch):
    idx = s.find(ch)
    if idx == -1:
        return s
    return s[idx] + s[:idx] + s[idx + 1:]

def is_weekday_name(s):
    names = {'Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'}
    return s in names

def longest_decreasing_run_length(lst):
    if not lst:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            cur += 1
        else:
            cur = 1
        best = max(best, cur)
    return best

def oxford_join_custom(items, conj):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} {conj} {items[1]}"
    return ", ".join(items[:-1]) + f", {conj} {items[-1]}"

def count_pairs(pairs):
    d = {}
    for p in pairs:
        t = tuple(p)
        d[t] = d.get(t, 0) + 1
    return d

def group_and_sort_by_key(records):
    groups = {}
    for cat, val in records:
        groups.setdefault(cat, []).append(val)
    return {cat: sorted(vals) for cat, vals in groups.items()}

def int_to_hex_string(n):
    if n == 0:
        return "0"
    return format(n, 'x')

def free_time_slots(intervals, day_start, day_end):
    result = []
    cur = day_start
    for s, e in intervals:
        if s > cur:
            result.append((cur, s))
        cur = max(cur, e)
    if cur < day_end:
        result.append((cur, day_end))
    return result

def next_month(year, month):
    if month == 12:
        return (year+1, 1)
    return (year, month+1)

def nth_weekday_from_end(year, month, weekday_num, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def wd(y, m, d):
        if m < 3:
            m += 12
            y -= 1
        K = y % 100
        J = y // 100
        h = (d + (13 * (m + 1)) // 5 + K + K // 4 + J // 4 + 5 * J) % 7
        return (h + 5) % 7
    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
    last_wd = wd(year, month, dim)
    diff = (last_wd - weekday_num) % 7
    last_occurrence = dim - diff
    return last_occurrence - (n - 1) * 7

def leetspeak(s):
    mapping = {'a': '4', 'e': '3', 'i': '1', 'o': '0', 's': '5', 't': '7'}
    out = []
    for ch in s:
        low = ch.lower()
        out.append(mapping[low] if low in mapping else ch)
    return ''.join(out)

def moving_average_2dp(lst, k):
    n = len(lst)
    if k <= 0 or k > n:
        return []
    res = []
    for i in range(n - k + 1):
        window = lst[i:i + k]
        res.append(round(sum(window) / k, 2))
    return res
